/**
 * Finds the length of the longest substring without repeating characters.
 * Uses a sliding window approach with O(n) time complexity.
 * @param {string} s - Input string
 * @returns {number} Length of longest substring without repeating characters
 */
function longestSubstring(s) {
    if (s.length === 0) return 0;

    const charSet = new Set();
    let left = 0;
    let maxLength = 0;

    for (let right = 0; right < s.length; right++) {
        // Remove characters from the left until the current character is not in the set
        while (charSet.has(s[right])) {
            charSet.delete(s[left]);
            left++;
        }

        // Add the current character to the set
        charSet.add(s[right]);

        // Update the maximum length if needed
        maxLength = Math.max(maxLength, right - left + 1);
    }

    return maxLength;
}

// Export for testing
if (typeof module !== 'undefined' && module.exports) {
    module.exports = longestSubstring;
}
