/**
 * Checks if a string has valid bracket nesting using a stack-based LIFO approach.
 * Non-bracket characters are ignored. Only (), [], and {} are considered.
 * 
 * @param {string} s - The input string to validate
 * @returns {boolean} True if all brackets are properly nested and closed, false otherwise
 * 
 * Complexity: O(n) time and O(n) worst-case space
 * - Time: Each character is processed exactly once (n = string length)
 * - Space: In the worst case (all opening brackets), the stack grows to O(n)
 */
function isValidBrackets(s) {
  // Handle non-string input
  if (typeof s !== 'string') {
    return false;
  }

  const stack = [];
  const bracketPairs = {
    '(': ')',
    '[': ']',
    '{': '}'
  };

  for (let i = 0; i < s.length; i++) {
    const char = s[i];

    // If it's an opening bracket, push to stack
    if (char in bracketPairs) {
      stack.push(char);
    } 
    // If it's a closing bracket
    else if (Object.values(bracketPairs).includes(char)) {
      // If stack is empty, there's no matching opening bracket
      if (stack.length === 0) {
        return false;
      }

      // Check if it matches the last opening bracket
      const lastOpening = stack.pop();
      if (bracketPairs[lastOpening] !== char) {
        return false;
      }
    }
    // Non-bracket characters are ignored
  }

  // If stack isn't empty, there are unclosed opening brackets
  return stack.length === 0;
}
```

